    v_dividers = sorted([c for c in range(cols) if all(grid[r][c] == 1 for r in range(rows))])

    if h_divider is None or not v_dividers:
        return grid

    # Get the left section (before first vertical divider)
    left_section_cols = list(range(v_dividers[0]))

    # For each row in top band, replicate left section to all three parts
    for r in range(h_divider):
        # Left part: columns 0 to v_dividers[0]-1
        for i, c in enumerate(left_section_cols):
            result[r][c] = grid[r][c]
        # Middle part: between dividers (v_dividers[0]+1 to v_dividers[1]-1)
        for i, c in enumerate(left_section_cols):
            result[r][v_dividers[0] + i + 1] = grid[r][c]
        # Right part: after last divider (v_dividers[-1]+1 to end)
        for i, c in enumerate(left_section_cols):
            result[r][v_dividers[-1] + i + 1] = grid[r][c]

    # Mirror bottom band to top band
    # Row 5 maps to row 3, 6 to 2, 7 to 1
    for r in range(h_divider + 1, rows):
        r_mirror = h_divider - (r - h_divider - 1)
        for c in range(cols):
            if c in v_dividers:
                result[r][c] = 1
            else:
                result[r][c] = grid[r_mirror][c]

    # Place divider columns
    for r in range(rows):
        for c in v_dividers:
            result[r][c] = 1

    return result

